package nl.salah.civicsignal.security;
import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.HttpServletResponse;import java.util.Map;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfiguration {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(AdminSecurityProperties p,PasswordEncoder e){return username->{if(!p.configured()||!p.username().equals(username))throw new UsernameNotFoundException("disabled");return User.withUsername(p.username()).password(e.encode(p.password())).roles("ADMIN").build();};}
 @Bean SecurityFilterChain security(HttpSecurity h,ObjectMapper json)throws Exception{h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).httpBasic(b->b.authenticationEntryPoint((r,x,e)->error(x,json,401,"UNAUTHORIZED","Niet geautoriseerd."))).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/v1/status","/actuator/health","/actuator/info","/api/v1/report-events","/api/v1/reports/search").permitAll().requestMatchers("/api/v1/admin/**","/actuator/**").hasRole("ADMIN").anyRequest().denyAll()).exceptionHandling(e->e.accessDeniedHandler((r,x,z)->error(x,json,403,"FORBIDDEN","Toegang geweigerd."))).headers(x->x.frameOptions(f->f.deny()).contentTypeOptions(c->{}).referrerPolicy(r->r.policy(org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter.ReferrerPolicy.NO_REFERRER)));return h.build();}
 private void error(HttpServletResponse r,ObjectMapper j,int s,String c,String m)throws java.io.IOException{r.setStatus(s);r.setHeader(HttpHeaders.WWW_AUTHENTICATE,"Basic realm=\"CivicSignal Admin\"");r.setHeader(HttpHeaders.CACHE_CONTROL,"no-store");r.setContentType(MediaType.APPLICATION_JSON_VALUE);j.writeValue(r.getOutputStream(),Map.of("code",c,"message",m));}
}
